const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const point = ee.Geometry.Point([-70.647985, -34.752733]);
  const region = point.buffer(1000); // 1km buffer
  const date2023 = '2023-12-18';
  const years = [2017, 2018, 2019, 2020, 2021, 2022];

  // Function to get MODIS snow cover image for a date
  function getSnowImage(date) {
    const modisTerra = ee.ImageCollection('MODIS/006/MOD10A1')
      .filterDate(date, ee.Date(date).advance(1, 'day'))
      .select('NDSI_Snow_Cover');

    const modisAqua = ee.ImageCollection('MODIS/006/MYD10A1')
      .filterDate(date, ee.Date(date).advance(1, 'day'))
      .select('NDSI_Snow_Cover');

    let col = modisTerra;
    if (modisTerra.size().getInfo() === 0) {
      col = modisAqua;
    }

    if (col.size().getInfo() === 0) {
      return null;
    }

    return col.first();
  }

  // 2. Get 2023 image
  const img2023 = getSnowImage(date2023);
  if (!img2023) {
    print("No image found for 2023-12-18.");
    print("<answer>C1</answer>");
    return;
  }

  // Process 2023 image
  const masked2023 = img2023.updateMask(img2023.lte(100)); // Values 0-100 are snow cover %
  const stats2023 = masked2023.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: region,
    scale: 1000,
    maxPixels: 1e9,
  });
  const mean2023 = stats2023.get('NDSI_Snow_Cover_mean');
  const count2023 = stats2023.get('NDSI_Snow_Cover_count');
  const mean2023Val = mean2023.getInfo();
  const count2023Val = count2023.getInfo();

  if (count2023Val === 0) {
    print("No valid snow pixels for 2023.");
    print("<answer>C2</answer>");
    return;
  }

  // 3. Get historical images (2017-2022)
  let historicalMeans = [];
  for (let year of years) {
    const date = `${year}-12-18`;
    const img = getSnowImage(date);

    if (!img) {
      print(`${year}: No image.`);
      continue;
    }

    const masked = img.updateMask(img.lte(100));
    const stats = masked.reduceRegion({
      reducer: ee.Reducer.mean().combine({
        reducer2: ee.Reducer.count(),
        sharedInputs: true
      }),
      geometry: region,
      scale: 1000,
      maxPixels: 1e9,
    });
    const mean = stats.get('NDSI_Snow_Cover_mean');
    const count = stats.get('NDSI_Snow_Cover_count');
    const meanVal = mean.getInfo();
    const countVal = count.getInfo();

    if (countVal > 0 && meanVal !== null) {
      historicalMeans.push(meanVal);
      print(`${year}: ${meanVal.toFixed(1)}% (${countVal} px)`);
    } else {
      print(`${year}: No valid pixels.`);
    }
  }

  // Check if we have any historical data
  if (historicalMeans.length === 0) {
    print("No valid historical data.");
    print("<answer>C2</answer>");
    return;
  }

  // Calculate historical average
  const histAvg = historicalMeans.reduce((a, b) => a + b, 0) / historicalMeans.length;

  // 4. Validation & Final Answer
  print(`2023: ${mean2023Val.toFixed(1)}% (${count2023Val} px)`);
  print(`Historical Avg (${historicalMeans.length} yrs): ${histAvg.toFixed(1)}%`);

  // Check for invalid values
  if (mean2023Val === null || !isFinite(mean2023Val) || histAvg === null || !isFinite(histAvg)) {
    print("<answer>C3</answer>");
    return;
  }

  // Snow cover % should be between 0-100
  if (mean2023Val < 0 || mean2023Val > 100 || histAvg < 0 || histAvg > 100) {
    print("<answer>C3</answer>");
    return;
  }

  // Final comparison
  if (mean2023Val > histAvg) {
    print("<answer>A</answer>");
  } else {
    print("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
